import unittest
from candidate import is_multiply_prime

class TestIsMultiplyPrime(unittest.TestCase):
    def test_is_multiply_prime_true(self):
        self.assertTrue(is_multiply_prime(30))

    def test_is_multiply_prime_false(self):
        self.assertFalse(is_multiply_prime(25))

    def test_is_multiply_prime_zero(self):
        self.assertFalse(is_multiply_prime(0))

    def test_is_multiply_prime_negative(self):
        self.assertFalse(is_multiply_prime(-30))

    def test_is_multiply_prime_one(self):
        self.assertFalse(is_multiply_prime(1))

    def test_is_multiply_prime_greater_than_100(self):
        self.assertFalse(is_multiply_prime(200))

    def test_is_multiply_prime_prime_number(self):
        self.assertFalse(is_multiply_prime(7))

    def test_is_multiply_prime_product_of_two_primes(self):
        self.assertFalse(is_multiply_prime(6))

    def test_is_multiply_prime_product_of_more_than_three_primes(self):
        self.assertFalse(is_multiply_prime(2 * 3 * 5 * 7))

    def test_is_multiply_prime_input_is_none(self):
        with self.assertRaises(TypeError):
            is_multiply_prime(None)

    def test_is_multiply_prime_input_is_not_integer(self):
        with self.assertRaises(TypeError):
            is_multiply_prime(30.5)

    def test_is_multiply_prime_input_is_string(self):
        with self.assertRaises(TypeError):
            is_multiply_prime('30')

if __name__ == '__main__':
    unittest.main()
